// Recursively compare deterministic A/A work/configuration, never clocks.
bool same(const J&a,const J&b){if(a.type!=b.type||a.scalar!=b.scalar||a.array.size()!=b.array.size()||a.object.size()!=b.object.size())return false;for(size_t i=0;i<a.array.size();i++)if(!same(a.array[i],b.array[i]))return false;for(auto&[k,v]:a.object){auto at=b.object.find(k);if(at==b.object.end()||!same(v,at->second))return false;}return true;}
std::string dump(const J&v){if(v.type=="string")return qstr(v.scalar);if(v.type=="literal")return v.scalar;std::string text=v.type=="array"?"[":"{";bool first=true;if(v.type=="array"){for(auto&x:v.array){if(!first)text+=",";first=false;text+=dump(x);}}else{for(auto&[k,x]:v.object){if(!first)text+=",";first=false;text+=qstr(k)+":"+dump(x);}}return text+(v.type=="array"?"]":"}");}
uint64_t u64(const J&v){auto n=num(v);require(n<=UINT64_MAX,"Integer overflow");return uint64_t(n);}
void envelope(const J&e){auto&v=e.at("resource_envelope");require(u64(v.at("cpu_count"))==1&&v.at("cpu_affinity").array.size()==1&&u64(v.at("cpu_affinity").at(0))==3&&u64(v.at("threads"))==1&&u64(v.at("rank_threads"))==1&&u64(v.at("online_target_threads"))==1&&u64(v.at("address_space_limit_bytes"))==12884901888ULL&&real(v.at("timeout_s"))==2100.,"Envelope mismatch");}
void answer(const J&row,P q,uint64_t expected_d,size_t index){require(u64(row.at("fixture_index"))==index&&truth(row.at("group_verified"))&&u64(row.at("exit_code"))==0,"Answer producer status/index mismatch");require(point(row.at("target"))==q&&point(row.at("published_q"))==q&&on(q)&&!q.inf&&mul(STUDY_R,q).inf,"Answer public-Q mismatch");auto d=u64(row.at("recovered_scalar"));require(d>0&&d<STUDY_R&&d==expected_d&&mul(d,STUDY_G)==q,"Canonical scalar replay failure");}
J meter_checker(const files::path&checker,const files::path&dir,const J&row,const files::path&out){auto id=row.at("id").scalar;auto base=dir/"base.jsonl",trace=dir/"rank.jsonl",answers=dir/"answers.jsonl",receipt=out/(id+".rank.json");auto seed=dec(num(row.at("rank_seed")));auto started=std::chrono::steady_clock::now();pid_t child=fork();require(child>=0,"fork failed");if(child==0){auto p=out/(id+".checker.log");int fd=open(p.c_str(),O_WRONLY|O_CREAT|O_EXCL,0644);if(fd<0)_exit(126);dup2(fd,1);dup2(fd,2);close(fd);execl(checker.c_str(),checker.c_str(),base.c_str(),trace.c_str(),answers.c_str(),seed.c_str(),receipt.c_str(),static_cast<char*>(nullptr));_exit(127);}int status=0;rusage usage{};require(wait4(child,&status,0,&usage)==child,"wait4 failed");auto wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();int code=WIFEXITED(status)?WEXITSTATUS(status):-1;std::ostringstream text;text<<std::setprecision(17)<<"{\"id\":"<<qstr(id)<<",\"return_code\":"<<code<<",\"raw_wait_status\":"<<status<<",\"wall_s\":"<<wall<<",\"cpu_user_s\":"<<usage.ru_utime.tv_sec+usage.ru_utime.tv_usec/1e6<<",\"cpu_system_s\":"<<usage.ru_stime.tv_sec+usage.ru_stime.tv_usec/1e6<<",\"peak_rss_bytes\":"<<uint64_t(usage.ru_maxrss)*1024<<",\"checker_sha256\":"<<qstr(digest(checker))<<"}";auto path=out/(id+".meter.json");create_new(path,text.str()+"\n");auto meter=read_json(path.string());require(code==0,"Independent rank checker failed; meter/log preserved");auto audit=read_json(receipt.string());require(audit.at("status").scalar=="PASS"&&u64(audit.at("columns"))==u64(row.at("candidate").at("columns"))&&u64(audit.at("expected_rank_seed"))==num(row.at("rank_seed"))&&u64(audit.at("answers"))==u64(row.at("target_count")),"Rank audit count/seed mismatch");require(audit.at("checker_executable_sha256").scalar==digest(checker)&&audit.at("base_sha256").scalar==digest(base)&&audit.at("trace_sha256").scalar==digest(trace)&&audit.at("answers_sha256").scalar==digest(answers),"Rank audit identity mismatch");return meter;}
