 auto holdouts=read_json((files::path(m.at("holdout_fixtures").scalar)/"validation_sidecar.json").string());auto training=read_json((files::path(m.at("training_fixtures").scalar)/"validation_sidecar.json").string());auto policy=read_json(m.at("rho_config").scalar);std::map<std::string,J> aa;
