 require(e.at("status").scalar=="COMPLETED_VERIFIED"&&u64(e.at("return_code"))==0&&!truth(e.at("timeout")),"Noncomplete process retained");auto target_rows=lines(row.at("target_file").scalar);auto answers=lines(dir/"answers.jsonl");require(answers.size()==n&&target_rows.size()==n&&row.at("target_indices").array.size()==n,"Target/answer count mismatch");auto seeds=ic?J{}:read_json(row.at("seed_file").scalar);if(!ic)require(seeds.array.size()==n,"Rho seed count mismatch");
 for(size_t j=0;j<n;j++){size_t target=u64(row.at("target_indices").at(j));const auto&side=is_aa?training.at("entries").at(0):holdouts.at("entries").at(target);P q=point(side.at("point"));require(point(target_rows[j])==q,"Public target order/sidecar mismatch");answer(answers[j],q,u64(side.at("scalar_validation_only")),j);if(ic){require(answers[j].at("kind").scalar=="compact_orbit_dlp_target","IC answer schema mismatch");}else{require(answers[j].at("kind").scalar=="n83_rho_matched_target"&&u64(answers[j].at("walk_seed"))==num(seeds.at(j))&&same(answers[j].at("optimization_config"),policy),"Rho seed/policy mismatch");require(!truth(answers[j].at("known_answer_input"))&&!truth(answers[j].at("validation_sidecar_opened")),"Rho known-answer input flag");}}
